/*
 * ONE LEARNER'S PROGRAMME, ASSEMBLED FROM ROWS (TASK-L170 §1, §0.5).
 *
 * A HELPER, NOT AN ENDPOINT: this component has no Request node, so it cannot
 * be called over HTTP (SB-003). `course` and `learnerProgramme` both place it,
 * and each applies its OWN projection to what it returns — the product's
 * `projectForLearner` / `projectForCoach`, two code paths and never an audience
 * flag on the assembly (L91, L116). What leaves this node is the SUPERSET, and
 * it never leaves the server for a learner, because `course` projects before
 * it responds.
 *
 * PORTED, NEVER RE-DERIVED. Sources, in the product's repo:
 *   KIND_ORDER, orderEntries, stepState, sessionState, assignmentState,
 *   evaluationState, resolveDerivedProgrammes, scopeToProgramme,
 *   entriesForProgramme, assembleTimeline  -> src/lib/server/timeline/model.ts
 *   currentProgramme                       -> src/lib/programme/current.ts
 *   prep states, the session view          -> src/lib/server/coach/sessions-service.ts
 *   completedAt only on a complete step    -> src/lib/server/delivery/service.ts
 *   a message's anchor                     -> src/lib/server/conversations/service.ts
 * tools/check-timeline-port.mjs compiles model.ts and compares every one of the
 * model functions here with it, at five instants.
 *
 * NO JOINS (§3). Each read below is one Records query, filtered by the learner
 * or by ids an earlier read produced; they run in parallel where nothing
 * depends on them. The count is stated in the component's comment and matches a
 * measurement (criterion 6).
 *
 * `now` is an ISO string, or '' for the server clock. The endpoint decides
 * whether a caller may set it (§0.6); this node never reads a caller.
 */

// ── The model (src/lib/server/timeline/model.ts) ──────────────────────────────

const KIND_ORDER = ['evaluation', 'session', 'assignment', 'lesson', 'submission', 'message', 'note', 'signal'];
const KIND_RANK = new Map(KIND_ORDER.map((k, i) => [k, i]));
const STATE_RANK = { done: 0, now: 1, ahead: 2 };

function orderEntries(entries) {
  return [...entries].sort((a, b) => {
    const band = STATE_RANK[a.state] - STATE_RANK[b.state];
    if (band !== 0) return band;
    const aDated = a.at === null ? 1 : 0;
    const bDated = b.at === null ? 1 : 0;
    if (aDated !== bDated) return aDated - bDated;
    if (a.at !== null && b.at !== null && a.at !== b.at) return a.at < b.at ? -1 : 1;
    if (a.position !== b.position) return a.position - b.position;
    const kind = (KIND_RANK.get(a.kind) ?? 0) - (KIND_RANK.get(b.kind) ?? 0);
    if (kind !== 0) return kind;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
}

function stepState(status) {
  if (status === 'complete') return 'done';
  if (status === 'locked') return 'ahead';
  return 'now';
}

// Instants only — never a calendar day (L93/L100). A cancelled session keeps its
// temporal state: calling it `done` early would agree it was missed.
function sessionState(startsAt, durationMinutes, now) {
  const start = startsAt.getTime();
  const end = start + durationMinutes * 60000;
  const t = now.getTime();
  if (t < start) return 'ahead';
  if (t < end) return 'now';
  return 'done';
}

// An unanswered brief past its date is `now`, never overdue (sprint 33 §5.7).
function assignmentState(dueAt, answered, now) {
  if (answered) return 'done';
  if (dueAt === null) return 'now';
  return dueAt.getTime() > now.getTime() ? 'ahead' : 'now';
}

// `due_on` is a calendar day read at its UTC end.
function evaluationState(dueOn, completedAt, now) {
  if (completedAt !== null) return 'done';
  if (dueOn === null) return 'now';
  const due = Date.parse(dueOn + 'T23:59:59.999Z');
  return due > now.getTime() ? 'ahead' : 'now';
}

// An answer belongs where its brief does; an anchored note where its anchor
// does; a FREE note keeps null (sprint 34 §5.3). One pass, no chain.
function resolveDerivedProgrammes(entries) {
  const byId = new Map(entries.map((e) => [e.id, e]));
  const byAssignment = new Map(
    entries.filter((e) => e.kind === 'assignment').map((e) => [e.assignmentId, e.programmeId])
  );
  return entries.map((e) => {
    if (e.programmeId !== null) return e;
    if (e.kind === 'submission' && e.source === 'assignment' && e.assignmentId) {
      const owner = byAssignment.get(e.assignmentId);
      return owner ? { ...e, programmeId: owner } : e;
    }
    if (e.kind === 'note' && e.note.anchor) {
      const target = byId.get(e.note.anchor.id);
      return target && target.programmeId ? { ...e, programmeId: target.programmeId } : e;
    }
    return e;
  });
}

function scopeToProgramme(entries, programmeId) {
  return entries.filter((e) => e.programmeId === programmeId);
}

function entriesForProgramme(entries, programmeId) {
  return entries.filter((e) => e.programmeId === programmeId || e.programmeId === null);
}

// Pure: everything it needs is in `sources`, and `now` is passed rather than read.
function assembleTimeline(sources, now) {
  const entries = [];
  sources.steps.forEach((step, index) => {
    entries.push({
      kind: 'lesson', id: 'lesson:' + step.conceptId, at: step.completedAt, anchor: step.conceptId,
      state: stepState(step.status), position: index, programmeId: sources.pathProgrammeId,
      conceptId: step.conceptId, title: step.title, rationale: step.rationale, status: step.status,
      confidence: step.confidence ?? null, reachedWowMoment: step.reachedWowMoment
    });
  });
  const ratingsBySession = new Map(sources.sessionRatings.map((r) => [r.sessionId, r.ratings]));
  for (const session of sources.sessions) {
    entries.push({
      kind: 'session', id: 'session:' + session.id, at: session.startsAt, anchor: null,
      state: sessionState(new Date(session.startsAt), session.durationMinutes, now), position: 0,
      programmeId: session.programmeId, session, ratings: ratingsBySession.get(session.id) ?? []
    });
  }
  for (const e of sources.evaluations) {
    entries.push({
      kind: 'evaluation', id: 'evaluation:' + e.id,
      at: e.completedAt ? e.completedAt.toISOString() : e.dueOn === null ? null : new Date(e.dueOn + 'T23:59:59.999Z').toISOString(),
      anchor: null, state: evaluationState(e.dueOn, e.completedAt, now), position: 0, programmeId: e.programmeId,
      evaluationId: e.id, evaluationKind: e.kind, dueOn: e.dueOn,
      completedAt: e.completedAt ? e.completedAt.toISOString() : null,
      summary: e.summary, criteria: e.criteria, nextStep: e.nextStep, ratings: e.ratings
    });
  }
  const answeredAssignments = new Set(sources.assignmentSubmissions.map((s) => s.assignmentId));
  for (const a of sources.assignments) {
    if (a.status === 'draft') continue; // a draft produces no entry, and this is the one place that is decided
    const answered = answeredAssignments.has(a.id);
    entries.push({
      kind: 'assignment', id: 'assignment:' + a.id, at: a.dueAt ? a.dueAt.toISOString() : null, anchor: null,
      state: assignmentState(a.dueAt, answered, now), position: 0, programmeId: a.programmeId,
      assignmentId: a.id, title: a.title, brief: a.brief, dueAt: a.dueAt ? a.dueAt.toISOString() : null,
      submissionModes: a.submissionModes, criteria: a.criteria ?? [], deliverableId: a.deliverableId,
      cohortId: a.cohortId, answered, withdrawn: a.status === 'withdrawn'
    });
  }
  for (const s of sources.artifactSubmissions) {
    entries.push({
      kind: 'submission', id: 'submission:artifact:' + s.conceptId + ':' + s.attempt, at: s.submittedAt,
      anchor: s.conceptId, state: 'done', position: 0, programmeId: sources.pathProgrammeId,
      source: 'artifact', conceptId: s.conceptId, assignmentId: null, attempt: s.attempt,
      evaluated: s.evaluated, deliverableId: s.deliverableId
    });
  }
  for (const s of sources.assignmentSubmissions) {
    entries.push({
      kind: 'submission', id: 'submission:assignment:' + s.id, at: s.submittedAt.toISOString(), anchor: null,
      state: 'done', position: 0, programmeId: null, source: 'assignment', conceptId: null,
      assignmentId: s.assignmentId, attempt: s.attempt, evaluated: s.evaluated, deliverableId: null
    });
  }
  for (const note of sources.notes) {
    entries.push({
      kind: 'note', id: 'note:' + note.id, at: note.createdAt, anchor: null, state: 'done', position: 0,
      programmeId: null, note
    });
  }
  for (const turn of sources.turns) {
    entries.push({
      kind: 'message', id: 'message:' + turn.id, at: turn.createdAt.toISOString(), anchor: turn.conceptId,
      state: 'done', position: 0, programmeId: null, conversationId: turn.conversationId,
      threadAnchor: turn.anchor, subject: turn.subject, authorRole: turn.authorRole, body: turn.body,
      read: turn.readAt !== null, unread: false
    });
  }
  for (const signal of sources.signals) {
    entries.push({
      kind: 'signal', id: 'signal:' + signal.id, at: signal.createdAt.toISOString(), anchor: signal.conceptId,
      state: 'done', position: 0, programmeId: null, signalKind: signal.kind, sectionId: signal.sectionId,
      utterance: signal.utterance
    });
  }
  return orderEntries(resolveDerivedProgrammes(entries));
}

// ── Which programme is current (src/lib/programme/current.ts) ─────────────────
// ONE rule in one owner. Prefers an unexpired end, so a programme nobody closed
// cannot tell somebody they are twenty-three things short (L123).
function currentProgramme(list, now) {
  const live = list.filter((p) => p.status === 'active' && p.archivedAt === null);
  if (live.length === 0) return null;
  const today = now.toISOString().slice(0, 10);
  const expired = (p) => p.endsOn !== null && p.endsOn < today;
  return [...live].sort((a, b) => {
    if (expired(a) !== expired(b)) return expired(a) ? 1 : -1;
    if (a.endsOn !== b.endsOn) {
      if (a.endsOn === null) return 1;
      if (b.endsOn === null) return -1;
      const nearestFirst = a.endsOn < b.endsOn ? -1 : 1;
      return expired(a) ? -nearestFirst : nearestFirst;
    }
    return a.createdAt < b.createdAt ? 1 : a.createdAt > b.createdAt ? -1 : 0;
  })[0];
}

// ── The pack's onboarding fact labels (src/lib/domain/loom/index.ts) ──────────
// Pack DATA served by the function, never a row (L169's own map). The check
// compares this constant with the product's pack, so it cannot drift silently.
const ONBOARDING_FACTS = [{"key": "projectGoal", "label": "What they want to build or understand"}, {"key": "buildOrUnderstand", "label": "Whether they are building a thing or making sense of one"}, {"key": "currentSkillLevel", "label": "Where they are starting from"}, {"key": "stackOrTools", "label": "Tools, stack or environment already in play"}];

// ── Reading rows ─────────────────────────────────────────────────────────────

/* Every read is `{ plain: true }` (OpenNoodl HLT-022): the row as it was saved,
   `objectId` on it, nested documents untouched. A default read turns each nested
   object into a Model with a generated id, which broke a lesson's section ids. */
const iso = (v) => (v === null || v === undefined || v === '' ? null : new Date(v).toISOString());
const dateOrNull = (v) => (iso(v) === null ? null : new Date(iso(v)));
const orNull = (v) => (v === undefined ? null : v);

async function readProgramme(Records, learnerId, now) {
  const q = (collection, where) => Records.query(collection, where, { limit: 1000, plain: true });
  const eq = (v) => ({ equalTo: v });
  /* An empty `containedIn` is replaced by a value no id can equal: ids are slugs and
     uuids and never hold a space or a bracket. It was '\u0000none' until TASK-L171 —
     SQLite takes a NUL byte in a text parameter and PostgreSQL refuses the whole query
     ("invalid byte sequence for encoding UTF8: 0x00"), so `course` and
     `learnerProgramme` answered 400 on Postgres and only the migration found it. */
  const within = (ids) => ({ containedIn: ids.length ? ids : ['(no ids)'] });

  // Round 1 — everything keyed on the learner alone, in parallel.
  const [contexts, programmes, paths, progress, members, sessionsOwn, notes, conversations, signals,
    assignmentsOwn, assignmentSubs, artifactSubs, deliverables, concepts] = await Promise.all([
    q('ProjectContext', { learnerId: eq(learnerId) }),
    q('Programme', { learnerId: eq(learnerId) }),
    q('LearningPath', { learnerId: eq(learnerId) }),
    q('Progress', { learnerId: eq(learnerId) }),
    q('CohortMember', { learnerId: eq(learnerId) }),
    q('CoachingSession', { learnerId: eq(learnerId) }),
    q('CoachNote', { learnerId: eq(learnerId) }),
    q('Conversation', { learnerId: eq(learnerId) }),
    q('Signal', { learnerId: eq(learnerId) }),
    q('Assignment', { learnerId: eq(learnerId) }),
    q('AssignmentSubmission', { learnerId: eq(learnerId) }),
    q('ArtifactSubmission', { learnerId: eq(learnerId) }),
    q('LearnerDeliverable', { learnerId: eq(learnerId) }),
    q('Concept', {})
  ]);

  // A removed member stops receiving the group's things (L103's removed_at).
  const cohortIds = members.filter((m) => orNull(m.removedAt) === null).map((m) => m.cohortId);
  const programmeIds = programmes.map((p) => p.programmeId);
  const pathIds = paths.map((p) => p.pathId);
  const conversationIds = conversations.map((c) => c.conversationId);
  const deliverableIds = deliverables.map((d) => d.deliverableId);

  // Round 2 — keyed on ids round 1 produced.
  const [steps, sessionsCohort, assignmentsCohort, messages, evaluations, dimensions, deliverableConcepts, cohorts] =
    await Promise.all([
      q('PathStep', { pathId: within(pathIds) }),
      q('CoachingSession', { cohortId: within(cohortIds) }),
      q('Assignment', { cohortId: within(cohortIds) }),
      q('ConversationMessage', { conversationId: within(conversationIds) }),
      q('ProgrammeEvaluation', { programmeId: within(programmeIds) }),
      q('ProgrammeDimension', { programmeId: within(programmeIds) }),
      q('DeliverableConcept', { deliverableId: within(deliverableIds) }),
      q('Cohort', { cohortId: within(cohortIds) })
    ]);

  const sessions = [...sessionsOwn, ...sessionsCohort];
  const sessionIds = sessions.map((s) => s.sessionId);
  const dimensionIds = dimensions.map((d) => d.dimensionId);
  const staffEmails = [...new Set([...sessions.map((s) => s.createdByEmail), ...notes.map((n) => n.authorEmail)].filter(Boolean))];

  // Round 3 — keyed on ids round 2 produced.
  const [prepRows, ratingRows, staffUsers] = await Promise.all([
    q('SessionPrep', { sessionId: within(sessionIds) }),
    q('DimensionRating', { dimensionId: within(dimensionIds) }),
    q('_User', { email: within(staffEmails) })
  ]);

  return { contexts, programmes, paths, steps, progress, cohorts, sessions, notes, conversations, messages,
    signals, assignments: [...assignmentsOwn, ...assignmentsCohort], assignmentSubs, artifactSubs,
    deliverables, deliverableConcepts, evaluations, dimensions, prepRows, ratingRows, staffUsers, concepts };
}

// ── Rows to the product's source shapes ──────────────────────────────────────

const COACH_FALLBACK_NAME = 'Your coach';

function buildPayload(rows, learnerId, now) {
  const titleOf = new Map(rows.concepts.map((c) => [c.conceptId, c.title]));
  const progressOf = new Map(rows.progress.map((p) => [p.conceptId, p]));
  const nameOf = new Map(
    rows.staffUsers.map((u) => {
      const name = [u.firstName, u.lastName].filter((s) => s && String(s).trim()).join(' ');
      return [u.email, name || COACH_FALLBACK_NAME];
    })
  );
  const cohortName = new Map(rows.cohorts.map((c) => [c.cohortId, c.name]));

  // Steps of ONE path, live only (L113's removed_at), in the planner's order.
  // completedAt is the progress row's stamp and ONLY on a complete step
  // (delivery/service.ts:433) — for anything else that stamp means "last touched".
  const stepsOf = (pathId) =>
    rows.steps
      .filter((s) => s.pathId === pathId && orNull(s.removedAt) === null)
      .sort((a, b) => a.position - b.position)
      .map((s) => {
        const prog = progressOf.get(s.conceptId);
        return {
          conceptId: s.conceptId, title: titleOf.get(s.conceptId) ?? s.conceptId, rationale: s.rationale,
          status: s.status, confidence: prog ? orNull(prog.confidence) : null,
          reachedWowMoment: prog ? Boolean(prog.reachedWowMoment) : false,
          completedAt: s.status === 'complete' ? (prog ? iso(prog.updatedAt) : null) : null
        };
      });

  // The live path is the most recent one (L89); a replan writes a new row (L86).
  const pathsNewestFirst = [...rows.paths].sort((a, b) => (iso(a.createdAt) < iso(b.createdAt) ? 1 : -1));
  const livePath = pathsNewestFirst[0] ?? null;

  // Prep states for THIS learner (sessions-service.ts prepStatesFor): a concept
  // from the live path (removed-but-complete still counts, L113 §4); a brief
  // from whether anything was sent in (L121) — never from a verdict.
  const liveSteps = livePath
    ? rows.steps.filter((s) => s.pathId === livePath.pathId && (orNull(s.removedAt) === null || s.status === 'complete'))
    : [];
  const stepStatus = new Map(liveSteps.map((s) => [s.conceptId, s.status]));
  const answered = new Set(rows.assignmentSubs.map((s) => s.assignmentId));
  const assignmentTitle = new Map(rows.assignments.map((a) => [a.assignmentId, a.title]));
  const prepState = (kind, id) => {
    if (kind === 'assignment') return answered.has(id) ? 'done' : 'not_yet';
    if (!stepStatus.has(id)) return 'not_on_path';
    return stepStatus.get(id) === 'complete' ? 'done' : 'not_yet';
  };

  /* EVERY ORDER THAT IS PART OF AN ANSWER IS STATED HERE, never inherited from
     the order rows come back in: a backend promises none, and the first live run
     returned a deliverable's concepts shuffled while the offline run, reading the
     seed in file order, passed. Ratings follow their dimension's position — the
     product leaves this order undefined (evaluation/service.ts has no ORDER BY on
     them), so the template chooses the one a reader would expect. */
  const dimensionPosition = new Map(rows.dimensions.map((d) => [d.dimensionId, d.position]));
  const ratingsFor = (key, value) =>
    rows.ratingRows
      .filter((r) => orNull(r[key]) === value)
      .sort((a, b) => (dimensionPosition.get(a.dimensionId) ?? 0) - (dimensionPosition.get(b.dimensionId) ?? 0))
      .map((r) => ({ dimensionId: r.dimensionId, score: r.score }));

  const sessions = rows.sessions.map((row) => ({
    id: row.sessionId, title: row.title, startsAt: iso(row.startsAt), durationMinutes: row.durationMinutes,
    meetingUrl: orNull(row.meetingLink), summary: orNull(row.summary), cancelledAt: iso(row.cancelledAt),
    createdByName: nameOf.get(row.createdByEmail) ?? COACH_FALLBACK_NAME,
    cohort: row.cohortId ? { id: row.cohortId, name: cohortName.get(row.cohortId) ?? '' } : null,
    prep: rows.prepRows
      .filter((p) => p.sessionId === row.sessionId)
      .sort((a, b) => a.position - b.position)
      .map((p) => {
        if (orNull(p.resourceLabel) !== null) {
          return { kind: 'resource', id: orNull(p.resourceStorageKey) ?? orNull(p.resourceUrl) ?? p.resourceLabel,
            title: p.resourceLabel, state: null, url: orNull(p.resourceUrl), storageKey: orNull(p.resourceStorageKey) };
        }
        const kind = orNull(p.assignmentId) !== null ? 'assignment' : 'concept';
        const id = kind === 'assignment' ? p.assignmentId : p.conceptId;
        const title = kind === 'assignment' ? assignmentTitle.get(id) ?? id : titleOf.get(id) ?? id;
        return { kind, id, title, state: prepState(kind, id) };
      }),
    programmeId: orNull(row.programmeId)
  }));
  const sessionRatings = sessions.map((s) => ({ sessionId: s.id, ratings: ratingsFor('sessionId', s.id) }));

  // Soft-deleted notes are gone from every read (L90). Visibility rides a
  // PRIVATE field that both projections remove; the learner's drops the note.
  const notes = rows.notes
    .filter((n) => orNull(n.deletedAt) === null)
    .map((n) => ({
      id: n.noteId, body: n.body, authorName: nameOf.get(n.authorEmail) ?? COACH_FALLBACK_NAME,
      sessionId: orNull(n.sessionId),
      anchor: orNull(n.anchorKind) !== null ? { kind: n.anchorKind, id: n.anchorId } : null,
      createdAt: iso(n.createdAt), editedAt: iso(n.editedAt), _visibility: n.visibility
    }));

  // A turn's anchor is its thread's lesson with the prefix stripped, and null
  // for anything else (conversations/service.ts, after 0039).
  const threadOf = new Map(rows.conversations.map((c) => [c.conversationId, c]));
  const turns = rows.messages
    .map((m) => {
      const thread = threadOf.get(m.conversationId) || {};
      const kind = orNull(thread.anchorKind);
      const anchorId = orNull(thread.anchorId);
      return {
        id: m.messageId, conversationId: m.conversationId, subject: orNull(thread.subject),
        conceptId: kind === 'lesson' && anchorId !== null ? anchorId.slice('lesson:'.length) : null,
        anchor: kind !== null ? { kind, id: anchorId } : null, authorRole: m.authorRole, body: m.body,
        createdAt: dateOrNull(m.createdAt), readAt: dateOrNull(m.readAt)
      };
    })
    .sort((a, b) => a.createdAt - b.createdAt);

  const evaluations = rows.evaluations.map((e) => ({
    id: e.evaluationId, kind: e.kind, dueOn: orNull(e.dueOn), completedAt: dateOrNull(e.completedAt),
    summary: orNull(e.summary), criteria: orNull(e.criteria) ?? [], nextStep: orNull(e.nextStep),
    ratings: ratingsFor('evaluationId', e.evaluationId), programmeId: e.programmeId
  }));

  const assignments = rows.assignments.map((a) => ({
    id: a.assignmentId, title: a.title, brief: a.brief, dueAt: dateOrNull(a.dueAt), status: a.status,
    submissionModes: a.submissionModes, criteria: orNull(a.criteria), deliverableId: orNull(a.deliverableId),
    cohortId: orNull(a.cohortId), programmeId: orNull(a.programmeId)
  }));
  const assignmentSubmissions = rows.assignmentSubs.map((s) => ({
    id: s.submissionId, assignmentId: s.assignmentId, attempt: s.attempt, submittedAt: dateOrNull(s.submittedAt),
    evaluated: orNull(s.evaluation) !== null
  }));
  // Newest first, then the later attempt — artifacts/service.ts's ORDER BY.
  const artifactSubmissions = [...rows.artifactSubs]
    .sort((a, b) => (iso(a.submittedAt) === iso(b.submittedAt) ? b.attempt - a.attempt : iso(a.submittedAt) < iso(b.submittedAt) ? 1 : -1))
    .map((s) => ({
    conceptId: s.conceptId, attempt: s.attempt, submittedAt: iso(s.submittedAt),
    evaluated: orNull(s.evaluation) !== null, deliverableId: orNull(s.deliverableId)
  }));
  const signals = rows.signals.map((s) => ({
    id: s.signalId, conceptId: s.conceptId, sectionId: orNull(s.sectionId), kind: s.kind,
    utterance: orNull(s.utterance), createdAt: dateOrNull(s.createdAt)
  }));

  const sourcesFor = (pathProgrammeId, steps) => ({
    pathProgrammeId, steps, sessions, notes, artifactSubmissions, assignments, assignmentSubmissions,
    turns, signals, evaluations, sessionRatings
  });

  const programmes = rows.programmes.map((p) => ({
    id: p.programmeId, status: p.status, archivedAt: iso(p.archivedAt), endsOn: orNull(p.endsOn), createdAt: iso(p.createdAt)
  }));
  const current = currentProgramme(programmes, now);

  // The live timeline: the live path's lessons plus everything else. Scoped to
  // the current programme the way the chart is (entriesForProgramme — this
  // programme and everything belonging to none); every OTHER programme is its
  // own history, a filter over its own assembly (L124), never a second assembler.
  const liveAssembly = assembleTimeline(
    sourcesFor(livePath ? orNull(livePath.programmeId) : null, livePath ? stepsOf(livePath.pathId) : []),
    now
  );
  const entries = current ? entriesForProgramme(liveAssembly, current.id) : liveAssembly;
  const history = current
    ? programmes
        .filter((p) => p.id !== current.id)
        .sort((a, b) => (a.createdAt < b.createdAt ? -1 : 1))
        .flatMap((p) => {
          const path = pathsNewestFirst.find((x) => orNull(x.programmeId) === p.id);
          // A programme that owns NO path has no lessons, so nothing inherits its
          // id through `pathProgrammeId` — L124 found the unconditional version
          // claiming the learner's artifact submissions from a different path.
          return scopeToProgramme(
            assembleTimeline(sourcesFor(path ? p.id : null, path ? stepsOf(path.pathId) : []), now),
            p.id
          );
        })
    : [];

  const context = rows.contexts[0] ?? null;
  const conceptsOf = new Map();
  // A deliverable's concepts in their own position (deliverables/service.ts: ORDER BY position).
  for (const dc of [...rows.deliverableConcepts].sort((a, b) => a.position - b.position)) {
    conceptsOf.set(dc.deliverableId, [...(conceptsOf.get(dc.deliverableId) ?? []), dc.conceptId]);
  }
  return {
    learnerId,
    projectName: context ? orNull(context.projectName) : null,
    problemStatement: context ? orNull(context.problemStatement) : null,
    endsOn: current ? current.endsOn : null,
    entries,
    history,
    dimensions: rows.dimensions
      .map((d) => ({ id: d.dimensionId, programmeId: d.programmeId, label: d.label, target: d.target,
        deliverableId: orNull(d.deliverableId), position: d.position, archivedAt: iso(d.archivedAt) }))
      .sort((a, b) => a.position - b.position),
    deliverables: rows.deliverables
      .map((d) => ({ id: d.deliverableId, slug: d.slug, code: d.slug, labelKey: d.slug, title: d.title,
        description: orNull(d.description), expectedCoreFields: orNull(d.expectedCoreFields) ?? [],
        position: d.position, archivedAt: iso(d.archivedAt), conceptIds: conceptsOf.get(d.deliverableId) ?? [] }))
      .sort((a, b) => a.position - b.position),
    facts: context && orNull(context.facts) !== null ? context.facts : {},
    submissions: artifactSubmissions.map((s) => ({ conceptId: s.conceptId, attempt: s.attempt,
      submittedAt: s.submittedAt, evaluated: s.evaluated, deliverableId: s.deliverableId })),
    /* WHAT WAS SENT, AND WHAT CAME BACK (TASK-L182). The learner's own work with
       its text and its evaluation — from the two submission queries above, so no
       new query. The timeline entries stay content-free (the product's shape),
       and `submissions` stays the dossier's projection; this is the one place
       a page reads the words. Oldest first, then artifact before a brief's
       answer, then the id — a total order, because the backend promises none. */
    work: [
      ...rows.artifactSubs.map((s) => ({ source: 'artifact', submissionId: s.submissionId, conceptId: s.conceptId,
        sectionId: orNull(s.sectionId), assignmentId: null, attempt: s.attempt, submittedAt: iso(s.submittedAt),
        content: orNull(s.content), linkUrl: null, evaluation: orNull(s.evaluation) })),
      ...rows.assignmentSubs.map((s) => ({ source: 'assignment', submissionId: s.submissionId, conceptId: null,
        sectionId: null, assignmentId: s.assignmentId, attempt: s.attempt, submittedAt: iso(s.submittedAt),
        content: orNull(s.content), linkUrl: orNull(s.linkUrl), evaluation: orNull(s.evaluation) }))
    ].sort((x, y) =>
      x.submittedAt !== y.submittedAt ? (x.submittedAt < y.submittedAt ? -1 : 1)
        : x.source !== y.source ? (x.source < y.source ? -1 : 1)
        : x.submissionId < y.submissionId ? -1 : x.submissionId > y.submissionId ? 1 : 0),
    onboardingFacts: ONBOARDING_FACTS
  };
}

// ── The node ─────────────────────────────────────────────────────────────────
/* ONE input, {learnerId, now}, so the node runs exactly once per request. Two
   inputs arriving on different passes would run it twice (rule 2), and a second
   `done` is a second answer to a request that has already been answered.
   `now` is '' for the server clock; the ENDPOINT decides whether a caller may
   set it (§0.6). A learner id of '' is a signed-in account with no learner — a
   first-class state that assembles to the fixture's own empty shapes. */
if (Inputs.query !== undefined) {
  (async () => {
    try {
      const learnerId = String(Inputs.query.learnerId || '');
      const now = Inputs.query.now ? new Date(Inputs.query.now) : new Date();
      if (Number.isNaN(now.getTime())) throw new Error('now is not an instant');
      const rows = await readProgramme(Noodl.Records, learnerId, now);
      Outputs.payload = buildPayload(rows, learnerId, now);
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      // Logged for the operator; the caller still gets one refusal body (the mcp/auth.ts rule).
      console.error('[dbt:Programme]', Outputs.error);
      Outputs.failed();
    }
  })();
}
